import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, min, max, step, smoothstep, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();
  root.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // Geometry – capsule‑like label (wide flat plane)
  const width = 1.0;
  const height = 0.34;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // Material with texture map and accent edge emissive
  const material = new MeshStandardNodeMaterial();
  material.transparent = true;
  material.roughness = 1.0;
  material.metalness = 0.0;
  material.emissiveIntensity = 1.5;

  // Accent edge via emissive node (thin border)
  const accentHex = (config.visualSpec?.colors?.accent) || '#ff2a38';
  const accentColor = new Color(accentHex);
  const accentVec = vec3(accentColor.r, accentColor.g, accentColor.b);

  // Edge mask: 1 near edges, 0 inside
  const edgeDist = min(
    min(uv.x, uv.y),
    min(step(uv.x, 0.0), step(uv.y, 0.0)) // placeholder for 1-uv, replaced below
  );
  // Proper distance to nearest edge (using min of four sides)
  const distToLeft = uv.x;
  const distToRight = sub(1.0, uv.x);
  const distToBottom = uv.y;
  const distToTop = sub(1.0, uv.y);
  const nearest = min(min(distToLeft, distToRight), min(distToBottom, distToTop));
  const edgeMask = step(smoothstep(0.0, 0.02, nearest), 1.0); // 1 on edge, 0 inside
  material.emissiveNode = mul(accentVec, edgeMask);

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --------------------------------------------------------------------
  // Interaction handlers ------------------------------------------------
  // --------------------------------------------------------------------
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(mesh.position, {
    y: mesh.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  root.userData.handlers = {
    hover: () => hoverTL.play(),
    hoverOut: () => hoverTL.reverse(),
    click: () => ctx.emit('hub-pricing.select'),
  };

  // Cleanup -------------------------------------------------------------
  root.userData.cleanup = () => {
    hoverTL.kill();
    geometry.dispose();
    material.dispose();
    // texture will be disposed by the engine when its reference count drops
  };

  return root;
}
